template.script:

document.addEventListener('DOMContentLoaded', function() {
  const popup = document.getElementById('simplePopup');
  const yesBtn = document.getElementById('yesBtn');
  const noBtn = document.getElementById('noBtn');
  const giftForm = document.getElementById('giftForm');
  const closeBtn = popup.querySelector('.popup-close');

  // Get product details from page
  const productName = document.querySelector('h2').textContent.trim();
  const priceText = document.querySelector('.h5.text-muted').textContent.trim();
  const price = parseFloat(priceText.replace(/[^\d.]/g, '')) || 0;
  const imageSrc = document.querySelector('.product-detail-image').src;

  // Open popup
  document.getElementById('addToCartBtn').addEventListener('click', function(e) {
    e.preventDefault();
    popup.style.display = 'block';
    giftForm.style.display = 'none';
    popup.querySelector('.button-group').style.display = 'flex';
    popup.querySelector('p').style.display = 'block';
  });

  // Close popup
  closeBtn.addEventListener('click', () => popup.style.display = 'none');
  popup.addEventListener('click', (e) => { if (e.target === popup) popup.style.display = 'none'; });

  // No → add directly
  noBtn.addEventListener('click', function() {
    addToCart();
    popup.style.display = 'none';
  });

  // Yes → show form
  yesBtn.addEventListener('click', function() {
    popup.querySelector('.button-group').style.display = 'none';
    popup.querySelector('p').style.display = 'none';
    giftForm.style.display = 'block';
  });

  // Form submit → add to cart
  giftForm.addEventListener('submit', function(e) {
    e.preventDefault();
    addToCart();
    popup.style.display = 'none';
    giftForm.reset();
  });

  function addToCart() {
    let cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const product = {
      name: productName,
      price: price,
      image: imageSrc,
      qty: 1
    };

    // Check if product already exists
    const existing = cart.find(item => item.name === productName);
    if (existing) {
      existing.qty += 1;
    } else {
      cart.push(product);
    }

    localStorage.setItem('cart', JSON.stringify(cart));

    // Update cart in header
    if (typeof window.updateCartCount === 'function') window.updateCartCount();
    if (typeof window.renderCart === 'function') window.renderCart();

    // Open cart drawer
    document.getElementById('cart-drawer').style.display = 'block';
    document.getElementById('cart-overlay').style.display = 'block';
  }
});
